// Semantic design tokens that do not depend on the school palette. Components use these names through CSS
// variables (app/theme.css, generated by lib/theme/css.ts); no component should hardcode a color.

export type Mode = 'light' | 'dark';

type Fixed = {
    /** Page background. */ bg: string;
    /** Cards and panels. */ surface: string;
    /** Dialogs, menus, dropdowns, toasts. */ 'surface-raised': string;
    /** Quiet inner blocks, secondary panels. */ 'surface-muted': string;
    /** Neutral hover and pressed backgrounds. */ 'surface-hover': string;
    /** Tracks, placeholders, sunken wells. */ 'surface-sunken': string;
    text: string;
    'text-secondary': string;
    /** Helper text, captions, placeholders (still WCAG AA on every surface). */ 'text-muted': string;
    /** Decorative and supporting icons (3:1). */ 'icon-muted': string;
    /** Dividers and card outlines (decorative). */ border: string;
    /** Boundaries of inputs and outlined controls (3:1). */ 'border-strong': string;
    /** The "OS" in the CampusOS logotype. */ 'logo-soft': string;
    'success-text': string; 'success-subtle': string; 'success-border': string; 'success-solid': string; 'on-success': string;
    'warning-text': string; 'warning-subtle': string; 'warning-border': string; 'warning-solid': string;
    'danger-text': string; 'danger-subtle': string; 'danger-border': string; danger: string; 'on-danger': string;
    'info-text': string; 'info-subtle': string; 'info-border': string;
    overlay: string; 'shadow-soft': string; 'shadow-strong': string;
    /** Darkest text color used on light fills in this mode (not emitted as a variable). */ ink: string;
} & Record<`course-${CourseColor}-${'bg' | 'border' | 'text' | 'solid'}`, string>;

/** Course and category colors. Students pick mint/blue/peach/purple per class; amber marks academic dates. */
export const COURSE_COLORS = ['mint', 'blue', 'peach', 'purple', 'amber'] as const;
export type CourseColor = typeof COURSE_COLORS[number];

