/**
 * Text/background pairs that must meet WCAG AA in both modes (4.5:1 text, 3:1 large text / graphics / control
 * boundaries). Checked by tests/theme.test.mjs for every mode and every curated palette.
 */
export const CONTRAST_PAIRS: { fg: string; bg: string; min: number }[] = [
    ...['bg', 'surface', 'surface-raised', 'surface-muted', 'surface-hover'].flatMap(bg => [
        { fg: 'text', bg, min: 4.5 }, { fg: 'text-secondary', bg, min: 4.5 }, { fg: 'text-muted', bg, min: 4.5 },
        { fg: 'icon-muted', bg, min: 3 }, { fg: 'border-strong', bg, min: 3 },
        { fg: 'accent-text', bg, min: 4.5 }, { fg: 'focus-ring', bg, min: 3 },
    ]),
    { fg: 'text', bg: 'surface-sunken', min: 4.5 },
    { fg: 'on-accent', bg: 'accent', min: 4.5 }, { fg: 'on-accent', bg: 'accent-hover', min: 4.5 },
    { fg: 'accent-text', bg: 'accent-subtle', min: 4.5 }, { fg: 'text', bg: 'accent-subtle', min: 4.5 },
    { fg: 'on-highlight', bg: 'highlight', min: 4.5 },
    { fg: 'on-brand', bg: 'brand-deep', min: 4.5 }, { fg: 'on-brand-muted', bg: 'brand-deep', min: 4.5 }, { fg: 'on-brand-accent', bg: 'brand-deep', min: 4.5 },
    ...['success', 'warning', 'danger', 'info'].flatMap(s => [{ fg: `${s}-text`, bg: `${s}-subtle`, min: 4.5 }, { fg: `${s}-text`, bg: 'surface', min: 4.5 }]),
    { fg: 'on-danger', bg: 'danger', min: 4.5 }, { fg: 'on-success', bg: 'success-solid', min: 4.5 },
    { fg: 'success-solid', bg: 'surface', min: 3 }, { fg: 'warning-solid', bg: 'surface', min: 3 }, { fg: 'danger', bg: 'surface', min: 3 },
    ...COURSE_COLORS.flatMap(c => [
        { fg: `course-${c}-text`, bg: `course-${c}-bg`, min: 4.5 }, { fg: `course-${c}-text`, bg: 'surface', min: 4.5 },
        { fg: `course-${c}-solid`, bg: 'surface', min: 3 }, { fg: `course-${c}-solid`, bg: `course-${c}-bg`, min: 2.5 },
    ]),
];
